                return Js.Cat("முந்தா ", house.Str(), "-ஆம் வீட்டில் உள்ளது; ", year.Str(), " ஆம் ஆண்டில் கலவையான பலன்கள் வரலாம். முக்கிய முடிவுகளுக்கு முன் உங்கள் ஜாதகத்தை ஆழமாகப் பார்த்துக்கொள்ளுங்கள்.");
            }
            if (Js.StrictEquals(locale, Js.S("kn")))
            {
                if (Js.StrictEquals(band, Js.S("favorable")))
                {
                    return Js.Cat("ಮುಂಥಾ ", house.Str(), "ನೇ ಭಾವದಲ್ಲಿರುವುದರಿಂದ ", year.Str(), " ವರ್ಷ ಸಾಮಾನ್ಯವಾಗಿ ಅನುಕೂಲಕರವಾಗಿರುತ್ತದೆ; ಗುರಿ ಸಾಧನೆ, ಸ್ಥಿರತೆ ಅಥವಾ ಆಧ್ಯಾತ್ಮಿಕ ಪ್ರಗತಿಯ ಸಾಧ್ಯತೆಗಳು ಹೆಚ್ಚುತ್ತವೆ.");
                }
                if (Js.StrictEquals(band, Js.S("challenging")))
                {
                    return Js.Cat("ಮುಂಥಾ ", house.Str(), "ನೇ ಭಾವದಲ್ಲಿರುವುದರಿಂದ ", year.Str(), " ವರ್ಷ ಸವಾಲಿನದಾಗಿರಬಹುದು. ಆರೋಗ್ಯ, ಖರ್ಚು ಅಥವಾ ಸಾಲಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ವಿಷಯಗಳಲ್ಲಿ ಎಚ್ಚರಿಕೆಯಿಂದಿರಿ.");
                }
                return Js.Cat("ಮುಂಥಾ ", house.Str(), "ನೇ ಭಾವದಲ್ಲಿದೆ; ", year.Str(), " ವರ್ಷದಲ್ಲಿ ಮಿಶ್ರ ಫಲಿತಾಂಶಗಳು ಸಾಧ್ಯ. ಮುಖ್ಯ ನಿರ್ಧಾರಗಳ ಮೊದಲು ನಿಮ್ಮ ಜಾತಕವನ್ನು ಆಳವಾಗಿ ಪರಿಶೀಲಿಸಿಕೊಳ್ಳಿ.");
            }
            if (Js.StrictEquals(locale, Js.S("ml")))
            {
                if (Js.StrictEquals(band, Js.S("favorable")))
                {
                    return Js.Cat("മുന്ഥ ", house.Str(), "-ാം ഭാവത്തിലായതിനാൽ ", year.Str(), " വർഷം പൊതുവെ അനുകൂലമായിരിക്കും; ലക്ഷ്യപ്രാപ്തി, സ്ഥിരത, ആത്മീയ പുരോഗതി എന്നിവയ്ക്കുള്ള സാധ്യതകൾ വർധിക്കും.");
                }
                if (Js.StrictEquals(band, Js.S("challenging")))
                {
                    return Js.Cat("മുന്ഥ ", house.Str(), "-ാം ഭാവത്തിലായതിനാൽ ", year.Str(), " വർഷം വെല്ലുവിളി നിറഞ്ഞതാകാം. ആരോഗ്യം, ചെലവ്, കടം എന്നിവയുമായി ബന്ധപ്പെട്ട കാര്യങ്ങളിൽ ശ്രദ്ധ പുലർത്തുക.");
                }
                return Js.Cat("മുന്ഥ ", house.Str(), "-ാം ഭാവത്തിലാണ്; ", year.Str(), " വർഷത്തിൽ സമ്മിശ്ര ഫലങ്ങൾ ഉണ്ടാകാം. പ്രധാന തീരുമാനങ്ങൾക്കു മുമ്പ് നിങ്ങളുടെ ജാതകം ആഴത്തിൽ പരിശോധിക്കുക.");
            }
            if (Js.StrictEquals(locale, Js.S("gu")))
            {
                if (Js.StrictEquals(band, Js.S("favorable")))
                {
                    return Js.Cat("મુંથા ભાવ ", house.Str(), "માં હોવાથી વર્ષ ", year.Str(), " સામાન્ય રીતે અનુકૂળ રહે છે; લક્ષ્યપ્રાપ્તિ, સ્થિરતા અથવા આધ્યાત્મિક પ્રગતિની સંભાવનાઓ વધે છે.");
                }
                if (Js.StrictEquals(band, Js.S("challenging")))
                {
                    return Js.Cat("મુંથા ભાવ ", house.Str(), "માં હોવાથી વર્ષ ", year.Str(), " પડકારરૂપ બની શકે છે. સ્વાસ્થ્ય, ખર્ચ અથવા ઋણ સંબંધિત બાબતોમાં સાવધાની રાખજો.");
                }
                return Js.Cat("મુંથા ભાવ ", house.Str(), "માં સ્થિત છે; વર્ષ ", year.Str(), "માં મિશ્ર પરિણામ સંભવ છે. મહત્ત્વના નિર્ણયો પહેલાં આપની કુંડળીને ઊંડાણથી તપાસી લેજો.");
            }
            if (Js.StrictEquals(locale, Js.S("bn")))
            {
                if (Js.StrictEquals(band, Js.S("favorable")))
                {
                    return Js.Cat("মুন্থার অবস্থান ভাব ", house.Str(), ", তাই ", year.Str(), " সাল সাধারণত অনুকূল থাকে; লক্ষ্যপূরণ, স্থিতি বা আধ্যাত্মিক অগ্রগতির সম্ভাবনা বাড়ে।");
                }
                if (Js.StrictEquals(band, Js.S("challenging")))
                {
                    return Js.Cat("মুন্থার অবস্থান ভাব ", house.Str(), ", তাই ", year.Str(), " সাল কিছুটা কঠিন হতে পারে। স্বাস্থ্য, খরচ বা ঋণের ব্যাপারে সাবধান থাকবেন।");
                }
                return Js.Cat("মুন্থার অবস্থান ভাব ", house.Str(), "; ", year.Str(), " সালে মিশ্র ফল দেখা দিতে পারে। বড় সিদ্ধান্তের আগে নিজের কুণ্ডলী ভালো করে দেখে নেবেন।");
            }
            if (Js.StrictEquals(locale, Js.S("pa")))
            {
                if (Js.StrictEquals(band, Js.S("favorable")))
                {
                    return Js.Cat("ਮੁੰਥਾ ਦਾ ਭਾਵ ", house.Str(), " ਵਿੱਚ ਹੋਣਾ ਸਾਲ ", year.Str(), " ਨੂੰ ਆਮ ਤੌਰ 'ਤੇ ਅਨੁਕੂਲ ਬਣਾਉਂਦਾ ਹੈ; ਟੀਚੇ ਪੂਰੇ ਹੋਣ, ਟਿਕਾਅ ਜਾਂ ਅਧਿਆਤਮਕ ਤਰੱਕੀ ਦੀ ਸੰਭਾਵਨਾ ਵਧਦੀ ਹੈ।");
                }
                if (Js.StrictEquals(band, Js.S("challenging")))
                {
                    return Js.Cat("ਮੁੰਥਾ ਦਾ ਭਾਵ ", house.Str(), " ਵਿੱਚ ਹੋਣਾ ਸਾਲ ", year.Str(), " ਨੂੰ ਕੁਝ ਚੁਣੌਤੀ ਭਰਿਆ ਬਣਾ ਸਕਦਾ ਹੈ। ਸਿਹਤ, ਖ਼ਰਚ ਜਾਂ ਕਰਜ਼ੇ ਨਾਲ ਜੁੜੇ ਮਾਮਲਿਆਂ ਵਿੱਚ ਸਾਵਧਾਨੀ ਰੱਖੋ।");
                }
                return Js.Cat("ਮੁੰਥਾ ਭਾਵ ", house.Str(), " ਵਿੱਚ ਹੈ; ਸਾਲ ", year.Str(), " ਵਿੱਚ ਮਿਲੇ-ਜੁਲੇ ਨਤੀਜੇ ਆ ਸਕਦੇ ਹਨ। ਵੱਡੇ ਫ਼ੈਸਲਿਆਂ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੀ ਕੁੰਡਲੀ ਨੂੰ ਡੂੰਘਾਈ ਨਾਲ ਜਾਂਚ ਲਓ।");
            }
            if (Js.StrictEquals(band, Js.S("favorable")))
            {
                return Js.Cat("Muntha in house ", house.Str(), " makes ", year.Str(), " broadly favorable — increased likelihood of goal attainment, stability, or spiritual progress.");
            }
            if (Js.StrictEquals(band, Js.S("challenging")))
            {
                return Js.Cat("Muntha in house ", house.Str(), " may make ", year.Str(), " challenging. Exercise care around health, expenditure, or debt-related matters.");
            }
            return Js.Cat("Muntha sits in house ", house.Str(), " — ", year.Str(), " likely brings mixed results. Study your chart closely before major decisions.");
        }

        internal static Js renderVarshaphalHtml(Js data, Js branding)
        {
            data = Shared.withoutNullItems(Js.Obj(
                Js.Spread(data),
                Js.Prop("Locale", Shared.safeLocale(data.Get("Locale")))), Js.Undefined);
            Js resolved = Shared.resolveBranding(data.Get("Branding"), branding);
            Js t = Shared.makeLabeler(Varshaphal.LABELS, data.Get("Locale"));
            Js loc = ((data.Get("Locale") && Locales.own(Varshaphal.LABELS, data.Get("Locale"))) ? data.Get("Locale") : Js.S("en"));
            Js subject = (data.Get("Subject").NonNullish ?? Js.Obj());
            Js asc = (data.Get("Ascendant").NonNullish ?? Js.Obj());
            Js muntha = (data.Get("Muntha").NonNullish ?? Js.Obj());
            Js lord = (data.Get("VarshaLord").NonNullish ?? Js.Obj());
            Js planets = (Js.IsArray(data.Get("Planets")) ? data.Get("Planets") : Js.Arr());
            Js year = (Js.StrictEquals(Js.TypeOf(data.Get("TargetYear")), Js.S("number")) ? data.Get("TargetYear") : Js.N(0d));
            Js coverMeta = Js.Cat(Shared.esc(t.Call(Js.S("born"))).Str(), " ", Shared.esc(subject.Get("BirthDate")).Str(), " ", Shared.esc(t.Call(Js.S("at"))).Str(), " ", Shared.esc(subject.Get("BirthTime")).Str(), "<br>", Shared.esc(subject.Get("BirthPlace")).Str());
            Js cover = Js.Cat("<section class=\"cover\">\n  ", Shared.coverBrandingHtml(resolved).Str(), "\n  <h1>", Shared.esc(t.Call(Js.S("title_varsha"))).Str(), "</h1>\n  <div class=\"year-badge\">", Shared.esc(data.Get("TargetYear")).Str(), "</div>\n  <div class=\"subject\">", Shared.esc(subject.Get("Name")).Str(), "</div>\n  <div class=\"meta\">", coverMeta.Str(), "</div>\n  <div class=\"generated\">", Shared.esc(t.Call(Js.S("generated"))).Str(), " ", Shared.esc(Varshaphal.formatGenerated(data.Get("GeneratedAt"))).Str(), "</div>\n</section>");
            Js solarReturn = Js.Cat("<h2>", Shared.esc(t.Call(Js.S("section_solar_return"))).Str(), "</h2>\n<p>\n  <strong>", Shared.esc(t.Call(Js.S("solar_return_at"))).Str(), ":</strong> ", Shared.esc((data.Get("SolarReturnLocal") || Varshaphal.formatGenerated(data.Get("SolarReturnISO")))).Str(), "<br>\n  <strong>", Shared.esc(t.Call(Js.S("ascendant"))).Str(), ":</strong>\n  ", Shared.esc(asc.Get("sign")).Str(), " (", Shared.esc(asc.Get("dms_within")).Str(), ") —\n  ", Shared.esc(t.Call(Js.S("nakshatra"))).Str(), ": ", Shared.esc(asc.Get("nakshatra")).Str(), ",\n  ", Shared.esc(t.Call(Js.S("pada"))).Str(), " ", Shared.esc(asc.Get("pada")).Str(), "\n</p>");
            Js indicators = Js.Cat("<div class=\"indicator-grid\">\n  <div class=\"indicator-card\">\n    <div class=\"label\">", Shared.esc(t.Call(Js.S("muntha"))).Str(), "</div>\n    <div class=\"value\">", Shared.esc(muntha.Get("sign")).Str(), "</div>\n    <div class=\"detail\">", Shared.esc(t.Call(Js.S("house"))).Str(), " ", Shared.esc(muntha.Get("house")).Str(), " ", Shared.esc(t.Call(Js.S("from_natal_lagna"))).Str(), "</div>\n  </div>\n  <div class=\"indicator-card\">\n    <div class=\"label\">", Shared.esc(t.Call(Js.S("varsha_lord"))).Str(), "</div>\n    <div class=\"value\">", Shared.esc(lord.Get("name")).Str(), "</div>\n    <div class=\"detail\">", Shared.esc(t.Call(Js.S("hora_number"))).Str(), " ", Shared.esc(lord.Get("hora")).Str(), "</div>\n  </div>\n</div>");
            Js planetRows = planets.Map(Js.Fn(args1_ =>
            {
                Js pl = Js.Arg(args1_, 0);
                Js p = (pl.Get("placement").NonNullish ?? Js.Obj());
                Js retro = (pl.Get("retro") ? Js.S(" (R)") : Js.S(""));
                return Js.Cat("<tr><td>", Shared.esc(pl.Get("name")).Str(), retro.Str(), "</td><td>", Shared.esc(p.Get("sign")).Str(), "</td><td>", Shared.esc(p.Get("dms_within")).Str(), "</td><td>", Shared.esc(pl.Get("house_num")).Str(), "</td><td>", Shared.esc(p.Get("nakshatra")).Str(), " (", Shared.esc(p.Get("pada")).Str(), ")</td></tr>");
            })).Join(Js.S(""));
            Js planetsTable = Js.Cat("<h2>", Shared.esc(t.Call(Js.S("section_planets_sr"))).Str(), "</h2>\n<table>\n  <thead>\n    <tr>\n      <th>", Shared.esc(t.Call(Js.S("planet"))).Str(), "</th>\n      <th>", Shared.esc(t.Call(Js.S("sign"))).Str(), "</th>\n      <th>", Shared.esc(t.Call(Js.S("degree"))).Str(), "</th>\n      <th>", Shared.esc(t.Call(Js.S("house"))).Str(), "</th>\n      <th>", Shared.esc(t.Call(Js.S("nakshatra"))).Str(), "</th>\n    </tr>\n  </thead>\n  <tbody>", planetRows.Str(), "</tbody>\n</table>");
            Js munthaHouse = (Js.StrictEquals(Js.TypeOf(muntha.Get("house")), Js.S("number")) ? muntha.Get("house") : Js.N(0d));
            Js outlook = Js.Cat("<h2>", Shared.esc(t.Call(Js.S("section_outlook"))).Str(), "</h2>\n<p>", Shared.esc(Varshaphal.outlookText(loc, year, Varshaphal.munthaBand(munthaHouse), munthaHouse)).Str(), "</p>");
            Js bodyHtml = Js.Arr(cover, solarReturn, indicators, planetsTable, outlook).Join(Js.S("\n\n"));
            return Shared.layoutDocument(Js.Obj(
                Js.Prop("lang", data.Get("Locale")),
                Js.Prop("title", Js.Cat(t.Call(Js.S("title_varsha")).Str(), " ", (data.Get("TargetYear").NonNullish ?? Js.S("")).Str(), " — ", (subject.Get("Name").NonNullish ?? Js.S("")).Str())),
                Js.Prop("branding", resolved),
                Js.Prop("bodyHtml", bodyHtml),
                Js.Prop("extraCss", Varshaphal.EXTRA_CSS)));
        }
    }
}
